;document.addEventListener("click", function (e) {
        var btn = e.target.closest(".record-copy");
        if (!btn) return;
        var code = btn.parentElement.querySelector("code");
        if (!code) return;
        navigator.clipboard
          .writeText(code.textContent.trim())
          .then(function () {
            var old = btn.textContent;
            btn.textContent = "Copied ✓";
            setTimeout(function () {
              btn.textContent = old;
            }, 1600);
          });
      });
